      "citation": "§ 98.0706(d)",
      "quote_parts": [
        {
          "segment_id": 16,
          "quoted_text": "If a residential rental property is offered for rent or lease for residential \npurposes within five years of the date the tenant was evicted under \nsections 98.0704(b)(1), (3), or (4), landlord shall first offer to lease the \nresidential rental property in writing to the tenant displaced from that unit by \nthe no-fault just cause termination if the tenant:   \n(1) advised the landlord in writing within 30 days of the termination \nnotice of the tenant’s desire to receive an offer to renew the tenancy; \nand  \n(2) provided the landlord a mailing address or email address for the \nlandlord to send the offer, including any change of mailing address or \nemail address.  \nThe landlord shall have the right to screen the tenant using industry accepted \nmethods and shall communicate the minimum screening criteria in the written \noffer for the new tenancy. The tenant shall have 30 days from the date of \nreceipt of the offer to accept."
        }
      ],
